    // (apps/claude-ai/components/Cowork/CoworkActiveDocBar.tsx). Each digit
    // is a 0-9 strip translated by -<digit>em on a transform transition;
    // columns key from the right so the ones place keeps identity as the
    // number widens. New columns paint at 0 then rAF-roll to target.
    var countEl = document.getElementById('count');
    var pluralEl = document.getElementById('plural');
    function makeCol() {
      var col = document.createElement('span');
      col.className = 'col';
      col.dataset.pos = '0';
      var clip = document.createElement('span');
      clip.className = 'clip';
      var strip = document.createElement('span');
      strip.className = 'strip';
      strip.style.transform = 'translateY(0)';
      // Two copies of 0-9 so a 9->0 wrap rolls forward into the second copy
      // instead of rewinding.
      for (var d = 0; d < 20; d++) {
        var cell = document.createElement('span');
        cell.className = 'cell';
        cell.textContent = String(d % 10);
        strip.appendChild(cell);
      }
      clip.appendChild(strip);
      col.appendChild(clip);
      return col;
    }
    function stripOf(col) { return col.firstChild.firstChild; }
    function setDigit(col, d) {
      var strip = stripOf(col);
      var pos = Number(col.dataset.pos);
      if (pos >= 10) {
        // Snap from second copy to the same digit in the first copy before
        // computing the next target, so position stays bounded.
        pos -= 10;
        strip.style.transition = 'none';
        strip.style.transform = 'translateY(-' + pos + 'em)';
        void strip.offsetHeight;
        strip.style.transition = '';
      }
      var target = d >= pos ? d : 10 + d;
      col.dataset.pos = String(target);
      strip.style.transform = 'translateY(-' + target + 'em)';
    }
    function setCount(n) {
      var s = String(n);
      var cols = countEl.children;
      while (cols.length < s.length) countEl.insertBefore(makeCol(), countEl.firstChild);
      while (cols.length > s.length) countEl.removeChild(countEl.firstChild);
      requestAnimationFrame(function () {
        for (var i = 0; i < s.length; i++) setDigit(cols[i], Number(s[i]));
      });
      pluralEl.textContent = n === 1 ? '' : 's';
    }
    setCount(0);
    var micEl = document.getElementById('mic');
    var lvlEl = document.getElementById('lvl');
    var doneEl = document.getElementById('done');
    var discardEl = document.getElementById('discard');
    var pillEl = document.querySelector('.pill');
    function setMicState(on, level) {
      micEl.classList.remove('err');
      micEl.title = '';
      micEl.classList.toggle('off', !on);
      micEl.setAttribute('aria-pressed', String(on));
      lvlEl.style.width = Math.round(Math.max(0, Math.min(1, level)) * 100) + '%';
      // Mic-off during Processing hides the meter (~26px); re-measure so the
      // pill isn't left sized for content that's no longer there.
      if (pillEl.classList.contains('processing')) { measureProcessingWidth(); }
    }
    function setMicError() {
      micEl.classList.add('off', 'err');
      micEl.setAttribute('aria-pressed', 'false');
      micEl.title = 'Narration disconnected — click to reconnect';
      lvlEl.style.width = '0%';
    }
    // Flip to the held "Processing…" state (spinner + shimmer label +
    // muted step count). The controls are hidden, not just disabled — the
    // recording is already captured and there's nothing left to act on;
    // the count stays as reassurance the work landed. Main tears this
    // window down via dismissWatchRecordPill once the session is showing.
    var warnInterval = null;
    // Report the laid-out content width so main can shrink the window to fit
    // exactly — the step count's digit count and the mic meter's presence both
    // move this, so measuring beats a guessed constant. Re-run whenever visible
    // content changes (e.g. the mic meter darkening on capture-stop).
    function measureProcessingWidth() {
      requestAnimationFrame(function () {
        var w = 0;
        var kids = pillEl.children;
        for (var i = 0; i < kids.length; i++) {
          var r = kids[i].getBoundingClientRect();
          if (r.width > 0) { w += r.width; }
        }
        var style = getComputedStyle(pillEl);
        var gaps = parseFloat(style.gap) * Math.max(0, visibleCount() - 1);
        var pad = parseFloat(style.paddingLeft) + parseFloat(style.paddingRight);
        window.cuWatchRecord.reportProcessingWidth(Math.ceil(w + gaps + pad));
      });
    }
    function setProcessing() {
      // Drop warn-on so the step count (.muted) shows in Processing; stop the countdown ticking a hidden chip.
      pillEl.classList.remove('warn-on');
      if (warnInterval) { clearInterval(warnInterval); warnInterval = null; }
      pillEl.classList.add('processing');
      doneEl.disabled = true;
      discardEl.disabled = true;
      micEl.disabled = true;
      measureProcessingWidth();
    }
    function visibleCount() {
      var n = 0;
      var kids = pillEl.children;
      for (var i = 0; i < kids.length; i++) {
        if (kids[i].getBoundingClientRect().width > 0) { n++; }
      }
      return n;
    }
    var warnEl = document.getElementById('timeWarn');
    function setTimeWarning(msRemaining) {
      var secondsRemaining = Math.round(msRemaining / 1000);
      warnEl.textContent = secondsRemaining + 's left';
      pillEl.classList.add('warn-on');
      warnInterval = setInterval(function () {
        secondsRemaining -= 1;
        if (secondsRemaining <= 0) { clearInterval(warnInterval); warnInterval = null; return; }
        warnEl.textContent = secondsRemaining + 's left';
      }, 1000);
    }
    micEl.onclick = function () { window.cuWatchRecord.toggleMic(); };
    doneEl.onclick = function () { window.cuWatchRecord.done(); };
    discardEl.onclick = function () { window.cuWatchRecord.discard(); };
    window.cuWatchRecord.onStepCount(setCount);
    window.cuWatchRecord.onMicState(setMicState);
    window.cuWatchRecord.onProcessing(setProcessing);
    window.cuWatchRecord.onTimeWarning(setTimeWarning);
    window.cuWatchRecord.onMicError(setMicError);
